#!/usr/bin/env bash
# Bundle item 156 commerce_videos_1122 (thread "Site: Add Commerce and Industry committee", 22 Nov 2569)
# Commerce 2569 videos from thread "Videos: Commerce and Industry committee meetings" (VIDEO AUTO-APPROVAL; 1080x1920, Thai voice +
# English subtitles burned in, legal STOP 0 WARN 0; sources Rpublic=1):
#   main 35 PRE (2:37, notice ว๑๐๔๐ ref 11216585)  - meets Wed 25 Nov 14.00, must be live before
#   smegov 18 PRE (1:47, notice ว๑๐๕๐ ref 11225978) - meets Tue 24 Nov 10.00, must be live before
#   main 34 POST (4:24, summary ref 11216297)       - 34 now has [pre, post]; the live pre entry is kept as it is
# Needs item 152 first (it adds meetings 35 and smegov 18). Media files embedded (md5-checked). Surgical: media field of those
# meetings in DATA + meetings.json / sub-smegov.json, CAPS tracks, video share pages (video_share.py CARD_BIG=1, every other
# s/v-*.html kept byte-identical, phone layer + no_video_dl on the new pages), home newest-4 video list + its English headline,
# then meeting_pages.py. Idempotent; no git, no network. Needs $HUB ($BUILD optional). run_bundle.sh moves the mp4s to a video repo.
set -euo pipefail
: "${HUB:?HUB not set}"; BUILD=${BUILD:-/mnt/project-files/archive/build}
T=156_commerce_videos_1122
M="$HUB/commerce/2569"
for f in index.html meetings.json sub-smegov.html sub-smegov.json i18n-en.json; do test -f "$M/$f" || { echo "$T: $M/$f missing" >&2; exit 1; }; done
test -f "$HUB/index.html" -a -f "$HUB/i18n-en.json" || { echo "$T: hub index.html / i18n-en.json missing" >&2; exit 1; }
PAY="$(mktemp -d)"; KEEP="$(mktemp -d)"; trap 'rm -rf "$PAY" "$KEEP"' EXIT
