tar -xzf "$PAY/p.tgz" -C "$PAY"; rm -f "$PAY/p.tgz"
(cd "$PAY" && md5sum -c --quiet MD5SUMS) || { echo "$T: embedded files damaged" >&2; exit 1; }
for v in v35pre:157 sub-smegov-v18pre:107 v34:264; do f=${v%%:*}; want=${v##*:}
  dur=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$PAY/media/$f.mp4")
  python3 -c "import sys; sys.exit(0 if abs(float('$dur')-$want)<2 else 1)" || { echo "$T: $f length $dur, expected ~$want s" >&2; exit 1; }
  wh=$(ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "$PAY/media/$f.mp4"); [ "$wh" = "1080,1920" ] || { echo "$T: $f size $wh" >&2; exit 1; }
  head -1 "$PAY/media/$f.th.vtt" | grep -q '^WEBVTT' || { echo "$T: $f vtt header" >&2; exit 1; }
done
mkdir -p "$M/media" "$M/img"
for f in v35pre sub-smegov-v18pre v34; do
  # skip the mp4 once video_offload has moved it to a video repo (the page then links /video-N/...)
  grep -q "/video-[0-9]*/commerce/2569/media/$f.mp4" "$M/index.html" "$M/sub-smegov.html" || { cmp -s "$PAY/media/$f.mp4" "$M/media/$f.mp4" || cp -f "$PAY/media/$f.mp4" "$M/media/$f.mp4"; }
  cmp -s "$PAY/media/$f.th.vtt" "$M/media/$f.th.vtt" || cp -f "$PAY/media/$f.th.vtt" "$M/media/$f.th.vtt"
done
for f in poster35pre.jpg poster-sub-smegov-18pre.jpg poster34.jpg; do cmp -s "$PAY/media/$f" "$M/img/$f" || cp -f "$PAY/media/$f" "$M/img/$f"; done
python3 "$PAY/apply_v.py" "$M" "$HUB" "$PAY/payload_156.json"
NEWP="v-34.html v-35-pre.html v-smegov-18-pre.html"
need=0; for b in $NEWP; do test -f "$M/s/$b" || need=1; done
for k in '"34":"s/v-34.html' '"35":"s/v-35-pre.html'; do grep -q "$k" "$M/index.html" || need=1; done
grep -q '"18":"s/v-smegov-18-pre.html' "$M/sub-smegov.html" || need=1
if [ $need = 1 ]; then
  for f in "$M"/s/v-*.html; do b=$(basename "$f"); case " $NEWP " in *" $b "*) ;; *) cp -p "$f" "$KEEP/$b";; esac; done
  CARD_BIG=1 python3 "$BUILD/video_share.py" "$M" https://parliamentx.com/commerce/2569 2569
  for b in $NEWP; do test -f "$M/s/$b" || { echo "$T: share page s/$b missing" >&2; exit 1; }; python3 "$BUILD/mobile.py" "$M/s/$b" >/dev/null; done
  python3 "$BUILD/no_video_dl.py" "$M/s"
  for f in "$KEEP"/*.html; do cmp -s "$f" "$M/s/$(basename "$f")" || cp -f "$f" "$M/s/$(basename "$f")"; done
fi
python3 "$BUILD/no_video_dl.py" --check "$M"
MP="$BUILD/meeting_pages.py"; test -s "$MP" || MP="$PAY/meeting_pages.py"
python3 "$MP" "$M" >/dev/null
python3 - "$M" "$HUB" <<'PY'
import json, sys
M, HUB = sys.argv[1], sys.argv[2]; dec = json.JSONDecoder()
def val(p, c):
    for l in open(p, encoding="utf-8").read().split("\n"):
        if l.startswith(c): return dec.raw_decode(l[len(c):])[0]
for h, j in (("index.html", "meetings.json"), ("sub-smegov.html", "sub-smegov.json")):
    for src in ({m["n"]: m for m in val(f"{M}/{h}", "const DATA=")}, {m["n"]: m for m in json.load(open(f"{M}/{j}", encoding="utf-8"))}):
        ks = lambda n: sorted(v["kind"] + ":" + v["ck"] for v in src[n]["media"]["videos"])
        if h == "index.html":
            assert ks(34) == ["post:34", "pre:34p"] and ks(35) == ["pre:35p"], "156: main media"
            assert ks(33) == ["post:33"], "156: main 33 video kept"
        else:
            assert ks(18) == ["pre:smegov-18p"] and ks(17) == ["pre:smegov-17p"], "156: smegov media"
t = open(f"{M}/index.html", encoding="utf-8").read(); g = open(f"{M}/sub-smegov.html", encoding="utf-8").read()
caps = val(f"{M}/index.html", "const CAPS="); gc = val(f"{M}/sub-smegov.html", "const CAPS=")
assert caps.get("34", "").startswith("WEBVTT") and caps.get("35p", "").startswith("WEBVTT") and gc.get("smegov-18p", "").startswith("WEBVTT"), "156: CAPS"
assert '"35":"s/v-35-pre.html' in t and '"18":"s/v-smegov-18-pre.html' in g, "156: VSHARE"
for b in ("v-34.html", "v-34-pre.html", "v-35-pre.html", "v-smegov-18-pre.html", "v-smegov-17-pre.html"):
    h = open(f"{M}/s/{b}", encoding="utf-8").read()
    assert '<style data-mb>' in h and 'id="novdl-css"' in h, f"156: s/{b} phone/no-download layer missing"
home = open(f"{HUB}/index.html", encoding="utf-8").read()
assert "commerce/2569/img/poster35pre.jpg" in home, "156: home video list"
assert "poster35pre.jpg" in open(f"{M}/m/35.html", encoding="utf-8").read() and "poster34.jpg" in open(f"{M}/m/34.html", encoding="utf-8").read(), "156: meeting pages show the videos"
print("156_commerce_videos_1122 OK")
PY
